@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700;800&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{font-family:'DM Sans',sans-serif;color:#f3ead4;background:#101611;font-synthesis:none;text-rendering:optimizeLegibility;--gold:#e4c581;--muted:#c0b9a5}*{box-sizing:border-box}html,body,#game{margin:0;width:100%;height:100%;overflow:hidden}body{background:#101611}#game{position:fixed;inset:0}canvas{display:block;width:100%;height:100%}#ui{position:fixed;inset:0;pointer-events:none;overflow:hidden}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:78px;padding:0 4.1%;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,13,11,.66),transparent)}.brand{display:flex;align-items:center;gap:11px;color:#f3ead4;text-decoration:none;font-family:Cinzel,serif;font-size:17px;font-weight:700;letter-spacing:3px}.brand-mark{color:var(--gold);font-size:30px;text-shadow:0 0 17px #e4c58188}.brand small{display:block;font:500 8px 'DM Sans',sans-serif;letter-spacing:3.3px;color:#c7c1af;margin-top:3px}.chapter{display:flex;align-items:center;gap:17px;color:#ddd4be;font-size:9px;letter-spacing:2.5px}.chapter i{font-style:normal;color:var(--gold)}.chapter-line{width:37px;height:1px;background:linear-gradient(90deg,transparent,#b59e6b)}.chapter-line:last-child{transform:rotate(180deg)}.icon-btn{pointer-events:auto;background:#18201bc9;color:#e3d5b6;border:1px solid #d5bd8540;border-radius:50%;width:35px;height:35px;font-size:17px;cursor:pointer}.quest-card{position:absolute;z-index:2;top:117px;left:4.1%;width:255px;padding:0 0 0 16px;border-left:1px solid #dec78b77;text-shadow:0 1px 5px #111}.quest-label{display:flex;align-items:center;gap:9px;font-size:9px;letter-spacing:2px;color:#d9c99e;font-weight:600}.quest-dot{width:6px;height:6px;border-radius:50%;background:#dfc57f;box-shadow:0 0 10px #e9cd81}.quest-card h2{font:500 25px/1.26 Cinzel,serif;letter-spacing:.3px;margin:15px 0 13px}.quest-card h2 em{font-weight:400;color:#e6cc91}.quest-rule{height:1px;background:linear-gradient(90deg,#d9c17b7a,transparent);width:100%;margin-bottom:13px}.quest-progress{display:flex;align-items:center;gap:5px;font-size:11px;color:#d4cbb7}.quest-progress>span:first-child{color:#f3da9f;font-weight:700}.progress-track{height:3px;width:62px;background:#d7c7a333;margin-left:7px}.progress-track i{height:100%;width:0;display:block;background:#e4c581;transition:width .3s}.quest-card p{font-size:11px;color:#cec7b6;margin:11px 0 18px}.quest-direction{display:flex;gap:8px;align-items:center;font-size:8px;letter-spacing:1.5px;color:#d5c9ae}.quest-direction .compass{font-size:15px;color:#e8d095}.quest-direction #portal-distance{margin-left:auto;color:#f4dfae}.location{position:absolute;top:112px;right:4.5%;display:flex;gap:11px;align-items:center;color:#e3d9c0;text-shadow:0 2px 6px #000}.location-icon{font-size:22px;color:#e8cf90}.location b,.location small{display:block;letter-spacing:2px}.location b{font-size:9px}.location small{font-size:7px;color:#b8ae98;margin-top:5px;letter-spacing:2.1px}.vignette{position:absolute;inset:0;box-shadow:inset 0 0 180px 45px #10161159;pointer-events:none}.hud-bottom{position:absolute;z-index:2;bottom:0;left:0;right:0;height:130px;padding:0 4.1% 22px;display:flex;align-items:flex-end;justify-content:space-between;background:linear-gradient(0deg,rgba(8,13,11,.82),transparent)}.player-status{display:flex;align-items:center;gap:11px;width:250px}.avatar{width:42px;height:42px;border:1px solid #d8bd7c88;background:#161d17;border-radius:50%;display:grid;place-items:center;color:#e4c581;font-size:22px;box-shadow:0 0 20px #0008}.status-bars{flex:1}.status-name{display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.5px;color:#dfd5be;margin-bottom:6px}.status-name span:last-child{color:#b4a98d}.bar{height:8px;display:flex;align-items:center;gap:6px;margin-top:4px}.bar-icon{font-size:9px}.bar-track{height:4px;background:#d9d4c426;flex:1;border-radius:4px;overflow:hidden}.bar-track i{display:block;width:100%;height:100%;border-radius:4px;transition:width .2s}.hp .bar-icon{color:#df9b82}.hp .bar-track i{background:linear-gradient(90deg,#b5493f,#e47961)}.mana .bar-icon{color:#92cbd0}.mana .bar-track i{background:linear-gradient(90deg,#4c9ca2,#72cad1)}.bar b{font-size:8px;font-weight:500;min-width:22px;text-align:right;color:#e0d6c1}.action-hint{position:absolute;bottom:41px;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:8px;letter-spacing:1.5px;color:#c4bca9;display:flex;align-items:center;gap:6px}.action-hint span{margin-left:4px}kbd{font:600 8px 'DM Sans';border:1px solid #ddd0aa66;border-radius:3px;padding:4px 6px;color:#ead8a8;background:#1a201b99}.hotbar{display:flex;gap:8px;align-items:flex-end}.skill{position:relative;width:49px;height:49px;background:linear-gradient(145deg,#272920e8,#111713ed);border:1px solid #ded0a344;border-radius:6px;color:#e5d7b7;cursor:pointer;pointer-events:auto;display:flex;flex-direction:column;justify-content:center;align-items:center;box-shadow:0 3px 12px #0007}.skill:hover,.skill.active{border-color:#e4c581a8}.skill-key{position:absolute;top:3px;left:5px;font-size:8px;color:#c8b787}.skill-symbol{font-size:19px;line-height:24px;color:#edcf89}.skill small{font-size:6px;letter-spacing:.6px;color:#c9c0ae;white-space:nowrap}.skill:nth-child(3) .skill-symbol{color:#d79083}.minimap{width:74px;height:74px;position:relative;display:grid;place-items:center;transform:translateY(12px)}.map-ring{width:65px;height:65px;border:1px solid #e1d0a55c;border-radius:50%;background:#111914ad;position:relative;overflow:hidden}.map-ring:before,.map-ring:after{content:'';position:absolute;background:#d6c89a25}.map-ring:before{width:1px;height:100%;left:50%}.map-ring:after{height:1px;width:100%;top:50%}.map-player{position:absolute;left:50%;top:51%;width:7px;height:7px;background:#f6dfa3;border-radius:50%;z-index:2;box-shadow:0 0 8px #f6dfa3}.map-portal{position:absolute;left:46%;top:15%;color:#70e1d5;font-size:12px}.map-dot{position:absolute;width:4px;height:4px;border-radius:50%;background:#e07666}.d1{top:63%;left:25%}.d2{top:37%;right:21%}.minimap>span{position:absolute;bottom:-5px;font-size:7px;letter-spacing:2px;color:#d0c4a7}.boss-warning{position:absolute;top:26%;left:50%;transform:translateX(-50%);color:#ffc4a0;font:500 12px Cinzel,serif;letter-spacing:3px;opacity:0;transition:opacity .4s;text-shadow:0 0 18px #f75e47}.boss-warning.show{opacity:1}.damage-flash{position:absolute;inset:0;background:#b7372d;opacity:0;pointer-events:none;transition:opacity .15s}.overlay{position:fixed;inset:0;z-index:10;display:flex;justify-content:center;align-items:center;background:linear-gradient(90deg,rgba(9,15,12,.53),rgba(9,15,12,.24) 52%,rgba(9,15,12,.35)),linear-gradient(0deg,#10161144,transparent 65%);pointer-events:auto}.intro-backdrop{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 43%,transparent 3%,#10161135 70%,#101611a6 120%)}.intro-content{position:relative;text-align:center;margin-top:-3vh;animation:rise .85s ease both}.eyebrow{display:flex;align-items:center;gap:13px;justify-content:center;font-size:9px;letter-spacing:3.8px;color:#ddc990}.eyebrow span{width:28px;height:1px;background:#d7c18580}.title-flourish{color:#e2c47e;font-size:24px;margin-top:24px;text-shadow:0 0 20px #d4ae5e}.intro-content h1{font:500 clamp(43px,6.1vw,76px)/1.07 Cinzel,serif;letter-spacing:5px;margin:7px 0 17px;text-shadow:0 4px 23px #060907}.intro-content h1 span{font-weight:400;color:#e4c987;letter-spacing:11px}.intro-copy{font:400 13px/1.9 'DM Sans',sans-serif;letter-spacing:.35px;color:#d1c9b8;margin:0 0 28px}.begin-btn{pointer-events:auto;margin:auto;display:flex;align-items:center;justify-content:center;gap:28px;padding:0 18px 0 25px;height:48px;min-width:237px;border:1px solid #e3c782;background:linear-gradient(100deg,#665531a6,#362f20b8);color:#f3e5c4;font:600 9px 'DM Sans',sans-serif;letter-spacing:2px;cursor:pointer;transition:background .2s,transform .2s;box-shadow:0 0 25px #d9b96619}.begin-btn:hover{background:#967b43a8;transform:translateY(-2px)}.begin-btn b{font-size:19px;font-weight:400;color:#ead28f}.controls-note{margin-top:27px;font-size:8px;letter-spacing:1.5px;color:#b7ad99}.controls-note span{color:#e7d5a5;margin:0 5px}.controls-note i{font-style:normal;color:#706b5b}.intro-footer{position:absolute;bottom:29px;left:4.1%;right:4.1%;display:flex;justify-content:space-between;font-size:7px;letter-spacing:2px;color:#d1c7b1a6}.hidden{display:none!important}.pause-overlay{position:fixed;z-index:9;inset:0;display:grid;place-items:center;background:#080e0bc9;pointer-events:auto}.pause-card{text-align:center}.pause-mark{font-size:28px;color:#e4c581}.pause-card h2{font:500 20px Cinzel;letter-spacing:3px;margin:17px 0 9px}.pause-card p{font-size:12px;color:#c9c0ae;margin-bottom:24px}.toast{position:absolute;top:70%;left:50%;transform:translate(-50%,10px);opacity:0;color:#f1d997;border:1px solid #d7bc6c77;background:#101611d9;padding:10px 18px;font-size:10px;letter-spacing:1.3px;transition:.3s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-controls,.mobile-tip{display:none}@keyframes rise{from{opacity:0;transform:translateY(15px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:700px){.topbar{height:57px;padding:0 18px}.brand{font-size:13px;letter-spacing:2px;gap:7px}.brand-mark{font-size:24px}.brand small{font-size:6px;letter-spacing:2px}.chapter{font-size:7px;gap:7px;letter-spacing:1.2px}.chapter-line{width:13px}.icon-btn{width:30px;height:30px}.quest-card{top:81px;left:18px;width:190px;padding-left:11px}.quest-card h2{font-size:19px;margin:9px 0}.quest-label{font-size:7px}.quest-progress{font-size:9px}.quest-card p{font-size:9px;margin:8px 0 11px}.quest-direction{font-size:7px}.location{top:83px;right:17px;gap:6px}.location b{font-size:7px;letter-spacing:1px}.location small{font-size:6px;letter-spacing:1px}.location-icon{font-size:17px}.hud-bottom{height:104px;padding:0 16px 14px;align-items:flex-end}.player-status{width:172px;gap:7px}.avatar{width:34px;height:34px;font-size:17px}.status-name{font-size:7px}.bar{height:7px}.action-hint{display:none}.hotbar{gap:5px}.skill{width:42px;height:44px}.skill-symbol{font-size:17px}.skill small{font-size:5px}.minimap{display:none}.mobile-controls{display:block;position:absolute;inset:0;pointer-events:none}.joystick{position:absolute;left:24px;bottom:128px;width:106px;height:106px;border-radius:50%;background:#d7d1bd1c;border:1px solid #e3d6ad55;pointer-events:auto;touch-action:none}.joy-knob{position:absolute;width:43px;height:43px;border-radius:50%;left:30px;top:30px;background:#c9b98462;border:1px solid #e6d39a88;box-shadow:0 2px 9px #0005}.mobile-attack,.mobile-dash{pointer-events:auto;position:absolute;border-radius:50%;display:grid;place-items:center;color:#f0d998;background:#1c211bbd;border:1px solid #dfc77b99;touch-action:none}.mobile-attack{right:25px;bottom:136px;width:64px;height:64px;font-size:24px}.mobile-dash{right:95px;bottom:120px;width:43px;height:43px;font-size:17px;color:#d4c5a1}.mobile-tip{display:block;position:absolute;bottom:111px;width:100%;text-align:center;font-size:7px;letter-spacing:1px;color:#ded3b193;pointer-events:none}.intro-content{margin-top:-2vh;padding:0 16px}.eyebrow{font-size:7px;letter-spacing:2.3px}.eyebrow span{width:15px}.intro-content h1{font-size:clamp(35px,10vw,55px);letter-spacing:3px}.intro-content h1 span{letter-spacing:6px}.intro-copy{font-size:11px}.controls-note{font-size:6px;letter-spacing:.8px;margin-top:20px}.intro-footer{font-size:6px;letter-spacing:1px;bottom:17px}.location{max-width:130px}.boss-warning{top:35%;font-size:9px;letter-spacing:1.5px;white-space:nowrap}}
@media(max-height:550px){.intro-content{transform:scale(.78);margin-top:-3vh}.quest-card{top:70px}.hud-bottom{height:93px}.joystick{bottom:100px}.mobile-attack{bottom:105px}.mobile-dash{bottom:95px}.mobile-tip{bottom:78px}}

import * as THREE from 'three';
import './style.css';

const $ = (id) => document.getElementById(id);
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a5bba8');
scene.fog = new THREE.FogExp2('#a5bba8', 0.012);
const camera = new THREE.PerspectiveCamera(48, innerWidth / innerHeight, .1, 180);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
document.querySelector('#game').appendChild(renderer.domElement);

scene.add(new THREE.HemisphereLight('#d8e6d3', '#454638', 2.15));
const sun = new THREE.DirectionalLight('#ffe3b0', 3.2);
sun.position.set(-16, 25, 12); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024);
sun.shadow.camera.left = -34; sun.shadow.camera.right = 34; sun.shadow.camera.top = 34; sun.shadow.camera.bottom = -34;
sun.shadow.bias = -.0005; scene.add(sun);
const fill = new THREE.DirectionalLight('#a2c8ce', 1.1); fill.position.set(13, 9, -18); scene.add(fill);
const clock = new THREE.Clock();
const mat = (color, roughness = .86, extra = {}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const mats = {
  grass: mat('#687653'), grass2: mat('#798260'), stone: mat('#77796b'), darkStone: mat('#454a43'), bark: mat('#51483a'), leaf: mat('#52664c'), leaf2: mat('#697657'),
  gold: mat('#d5b66e', .42, { metalness: .48 }), robe: mat('#344b47'), trim: mat('#ba9a5d', .46, { metalness: .35 }), skin: mat('#d5b68f'), steel: mat('#b8c2b9', .36, { metalness: .7 }),
  enemy: mat('#344444', .38, { emissive: '#102424', emissiveIntensity: .65 }), enemyLight: mat('#a8e8d8', .28, { emissive: '#56cbb4', emissiveIntensity: 2.5 }), crystal: mat('#75ead9', .24, { emissive: '#28bba7', emissiveIntensity: 2.1 }),
  portal: mat('#82e6d2', .25, { emissive: '#40d4bd', emissiveIntensity: 2.8, transparent: true, opacity: .8 }),
};
const ground = new THREE.Mesh(new THREE.PlaneGeometry(170, 170), mats.grass);
ground.rotation.x = -Math.PI / 2; ground.receiveShadow = true; scene.add(ground);
const world = new THREE.Group(); scene.add(world);
const rand = (() => { let s = 48621; return () => { s = (s * 16807) % 2147483647; return (s - 1) / 2147483646; }; })();
const addMesh = (parent, geometry, material, pos, scale, cast = true) => {
  const mesh = new THREE.Mesh(geometry, material); mesh.position.set(...pos); if (scale) mesh.scale.set(...scale); mesh.castShadow = cast; mesh.receiveShadow = true; parent.add(mesh); return mesh;
};
function makeTree(x, z, size = 1) {
  const g = new THREE.Group(); g.position.set(x, 0, z); world.add(g);
  addMesh(g, new THREE.CylinderGeometry(.22 * size, .38 * size, 2.7 * size, 7), mats.bark, [0, 1.15 * size, 0], null);
  for (let i = 0; i < 3; i++) {
    const r = (1.35 - i * .29) * size, y = (2.5 + i * .94) * size;
    const crown = addMesh(g, new THREE.IcosahedronGeometry(r, 1), i === 1 ? mats.leaf2 : mats.leaf, [0, y, 0], [1, 1.25, 1]);
    crown.rotation.y = rand() * 3;
  }
  return g;
}
function makeRock(x, z, size = 1, material = mats.stone) {
  const rock = addMesh(world, new THREE.DodecahedronGeometry(size, 0), material, [x, size * .5, z], [1, .7 + rand() * .5, .82]);
  rock.rotation.set(rand() * .4, rand() * 6, rand() * .25); return rock;
}
// Soft rolling ridges, ancient stone and a ring of forest frame the playable valley.
for (let i = 0; i < 24; i++) {
  const a = i / 24 * Math.PI * 2, radius = 30 + rand() * 9, x = Math.cos(a) * radius, z = Math.sin(a) * radius;
  const hill = addMesh(world, new THREE.IcosahedronGeometry(7 + rand() * 6, 1), i % 3 ? mats.grass2 : mats.grass, [x, 1.1, z], [1.35, .55 + rand() * .35, 1.2], false);
  hill.rotation.y = rand() * 2;
}
for (let i = 0; i < 90; i++) {
  const a = rand() * Math.PI * 2, r = 20 + rand() * 31, x = Math.cos(a) * r, z = Math.sin(a) * r;
  if (Math.abs(x) < 7 && z > -12 && z < 12) continue;
  makeTree(x, z, .65 + rand() * .85);
}
for (let i = 0; i < 85; i++) {
  const x = (rand() - .5) * 55, z = (rand() - .5) * 55;
  if (Math.abs(x) < 8 && Math.abs(z) < 14) continue;
  if (Math.hypot(x, z) > 31) continue;
  makeRock(x, z, .25 + rand() * .7, i % 4 === 0 ? mats.darkStone : mats.stone);
}
// Ruined paving, etched stones and the distant gate.
for (let i = 0; i < 35; i++) {
  const x = (rand() - .5) * 10, z = 5 + rand() * 10;
  const tile = addMesh(world, new THREE.BoxGeometry(1.15 + rand() * .6, .13, 1.05 + rand() * .4), i % 4 ? mats.darkStone : mats.stone, [x, .04, z]);
  tile.rotation.y = (rand() - .5) * .28;
}
const portalGroup = new THREE.Group(); portalGroup.position.set(0, 0, -22); world.add(portalGroup);
const archMat = mat('#626659', .72);
for (const x of [-3.35, 3.35]) {
  addMesh(portalGroup, new THREE.BoxGeometry(.78, 6.4, .9), archMat, [x, 3.2, 0]);
  addMesh(portalGroup, new THREE.BoxGeometry(1.2, .38, 1.35), mats.gold, [x, 6.48, 0]);
  addMesh(portalGroup, new THREE.BoxGeometry(.98, .28, 1.1), mats.darkStone, [x, .18, 0]);
}
const archTop = addMesh(portalGroup, new THREE.TorusGeometry(3.35, .47, 8, 24, Math.PI), archMat, [0, 6.35, 0]);
archTop.rotation.z = Math.PI;
const portalInner = new THREE.Mesh(new THREE.CircleGeometry(2.85, 32), mats.portal);
portalInner.position.set(0, 3.12, -.18); portalInner.scale.y = 1.05; portalGroup.add(portalInner);
const portalRim = new THREE.Mesh(new THREE.TorusGeometry(2.85, .075, 8, 48, Math.PI), mats.gold);
portalRim.rotation.z = Math.PI; portalRim.position.set(0, 6.25, -.1); portalGroup.add(portalRim);
for (let i = 0; i < 3; i++) {
  const rune = addMesh(portalGroup, new THREE.OctahedronGeometry(.28 - i * .04), mats.crystal, [0, 1 + i * 1.7, .35]);
  rune.rotation.x = .3;
}
const portalLight = new THREE.PointLight('#55dfcb', 3.2, 15); portalLight.position.set(0, 3.5, 1.2); portalGroup.add(portalLight);
const portalRuneRing = new THREE.Mesh(new THREE.TorusGeometry(4.5, .045, 6, 48), mats.gold); portalRuneRing.rotation.x = -Math.PI / 2; portalRuneRing.position.y = .12; portalGroup.add(portalRuneRing);
// Hero, an armored wanderer with a luminous sword and a wind-swept cloak.
const player = new THREE.Group(); scene.add(player); player.position.set(0, 0, 10);
const hero = new THREE.Group(); player.add(hero);
addMesh(hero, new THREE.CylinderGeometry(.38, .56, .28, 8), mats.darkStone, [0, .15, 0]);
addMesh(hero, new THREE.ConeGeometry(.43, .48, 8), mats.robe, [0, .52, 0]);
addMesh(hero, new THREE.CylinderGeometry(.32, .43, .68, 8), mats.robe, [0, 1.04, 0]);
addMesh(hero, new THREE.BoxGeometry(.67, .12, .12), mats.trim, [0, .83, -.28]);
addMesh(hero, new THREE.SphereGeometry(.27, 12, 10), mats.skin, [0, 1.56, 0]);
const hood = addMesh(hero, new THREE.SphereGeometry(.31, 10, 8, 0, Math.PI * 2, 0, Math.PI * .58), mats.darkStone, [0, 1.63, -.015]);
hood.scale.set(1.08, 1, 1.08);
addMesh(hero, new THREE.BoxGeometry(.28, .075, .12), mats.gold, [0, 1.53, .24]);
const eyeMat = new THREE.MeshStandardMaterial({ color: '#b3f6e8', emissive: '#64e9d1', emissiveIntensity: 2 });
for (const x of [-.095, .095]) addMesh(hero, new THREE.SphereGeometry(.035, 8, 8), eyeMat, [x, 1.58, .26]);
for (const side of [-1, 1]) {
  addMesh(hero, new THREE.SphereGeometry(.21, 8, 8), mats.steel, [side * .46, 1.08, 0], [1, .85, .8]);
  addMesh(hero, new THREE.CylinderGeometry(.105, .13, .52, 7), mats.robe, [side * .52, .72, .02], null).rotation.z = side * -.14;
  addMesh(hero, new THREE.SphereGeometry(.14, 8, 8), mats.skin, [side * .54, .43, .1]);
  addMesh(hero, new THREE.CylinderGeometry(.14, .18, .52, 7), mats.darkStone, [side * .18, .17, 0]);
  addMesh(hero, new THREE.BoxGeometry(.31, .12, .44), mats.steel, [side * .18, .05, .08]);
}
const swordPivot = new THREE.Group(); swordPivot.position.set(.56, .48, .1); hero.add(swordPivot);
addMesh(swordPivot, new THREE.CylinderGeometry(.045, .055, .38, 6), mats.gold, [0, -.16, 0]);
addMesh(swordPivot, new THREE.BoxGeometry(.35, .075, .09), mats.gold, [0, .06, 0]);
const blade = addMesh(swordPivot, new THREE.ConeGeometry(.115, 1.35, 5), mats.steel, [0, .77, 0]); blade.rotation.z = Math.PI;
addMesh(swordPivot, new THREE.ConeGeometry(.1, .18, 5), mats.crystal, [0, .12, 0]).rotation.z = Math.PI;
const heroLight = new THREE.PointLight('#8be8d5', .48, 3.4); heroLight.position.set(0, 1.2, .7); hero.add(heroLight);

const relics = [];
function makeRelic(x, z, index) {
  const group = new THREE.Group(); group.position.set(x, 1, z); world.add(group);
